package com.mdfoysal.jarvis.data.security

import android.security.keystore.KeyGenParameterSpec
import android.security.keystore.KeyProperties
import android.util.Base64
import java.security.KeyStore
import javax.crypto.Cipher
import javax.crypto.KeyGenerator
import javax.crypto.SecretKey
import javax.crypto.spec.GCMParameterSpec

/**
 * Android Keystore backed key management.
 *
 * A random AES-256 data-encryption key (DEK) is generated by [com.mdfoysal.jarvis.core.crypto.SecretBox]
 * and wrapped by a hardware-backed Keystore key (KEK). The wrapped DEK is what gets persisted,
 * so the actual encryption key never leaves the Keystore protection boundary.
 */
class KeystoreKeyProvider(
    private val alias: String = DEFAULT_ALIAS
) {

    private val keyStore: KeyStore by lazy {
        KeyStore.getInstance(ANDROID_KEYSTORE).apply { load(null) }
    }

    /** Returns the Keystore key, creating it on first use. */
    fun getOrCreateMasterKey(): SecretKey {
        val existing = keyStore.getKey(alias, null) as? SecretKey
        if (existing != null) return existing

        val generator = KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES, ANDROID_KEYSTORE)
        val spec = KeyGenParameterSpec.Builder(
            alias,
            KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT
        )
            .setBlockModes(KeyProperties.BLOCK_MODE_GCM)
            .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)
            .setKeySize(256)
            .setRandomizedEncryptionRequired(true)
            .build()
        generator.init(spec)
        return generator.generateKey()
    }

    /** Wraps raw key material with the Keystore key. Output is base64 of `iv || ciphertext`. */
    fun wrap(rawKey: ByteArray): String {
        val cipher = Cipher.getInstance(TRANSFORMATION)
        cipher.init(Cipher.ENCRYPT_MODE, getOrCreateMasterKey())
        val encrypted = cipher.doFinal(rawKey)
        val combined = ByteArray(cipher.iv.size + encrypted.size)
        System.arraycopy(cipher.iv, 0, combined, 0, cipher.iv.size)
        System.arraycopy(encrypted, 0, combined, cipher.iv.size, encrypted.size)
        return Base64.encodeToString(combined, Base64.NO_WRAP)
    }

    /** Unwraps key material; returns `null` when the payload cannot be decrypted. */
    fun unwrap(payload: String): ByteArray? = try {
        val combined = Base64.decode(payload, Base64.NO_WRAP)
        val iv = combined.copyOfRange(0, GCM_IV_LENGTH)
        val body = combined.copyOfRange(GCM_IV_LENGTH, combined.size)
        val cipher = Cipher.getInstance(TRANSFORMATION)
        cipher.init(Cipher.DECRYPT_MODE, getOrCreateMasterKey(), GCMParameterSpec(GCM_TAG_BITS, iv))
        cipher.doFinal(body)
    } catch (e: Exception) {
        null
    }

    /** True when the device offers a hardware backed keystore. */
    fun isHardwareBacked(): Boolean = try {
        val factory = javax.crypto.SecretKeyFactory.getInstance(
            KeyProperties.KEY_ALGORITHM_AES,
            ANDROID_KEYSTORE
        )
        val key = factory.generateSecret(
            javax.crypto.spec.PBEKeySpec(
                "probe".toCharArray(),
                ByteArray(16),
                1,
                256
            )
        )
        val info = keyStore.getEntry(alias, null) as? KeyStore.SecretKeyEntry
        val factoryInfo = info?.secretKey?.let {
            keyStore.getEntry(alias, null)
        }
        factoryInfo != null
    } catch (e: Exception) {
        false
    }

    companion object {
        const val DEFAULT_ALIAS = "jarvis_master_key_v1"
        private const val ANDROID_KEYSTORE = "AndroidKeyStore"
        private const val TRANSFORMATION = "AES/GCM/NoPadding"
        private const val GCM_IV_LENGTH = 12
        private const val GCM_TAG_BITS = 128
    }
}
